import React from "react";
import { graphql } from "gatsby";
import type { PageProps } from "gatsby";
import { AdminLayout } from "../../../../features/admin/components/AdminLayout";
import { ItineraryDetail } from "../../../../features/admin/components/ItineraryDetail";

export default function ItineraryDetailPage({ params }: PageProps) {
  return (
    <AdminLayout title="Itinerary detail">
      <ItineraryDetail itineraryId={params["itineraryId"]} />
    </AdminLayout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
